;ФёклаFK_SM=-FK_+PL        DW FK0+SM,FK1+SM,FK2+SM,FK3+SM,FK4+SM        DW FK5+SM,FK6+SM,FK7+SM,FK8+SM,FK9+SM		if RUSFK0     DB "Возьми, красавица!",SOBES        DB "Спасибо, мне это не нужно.",END		elseFK0     DB "Hi beauty! Take this.",SOBES        DB "Thank you. I don't need it.",END				endif		if RUSFK1     DB "Здравствуй, девушка!",SOBES        DB "Здравствуйте, бабушка!",HERO		elseFK1     DB "Hello girl!",SOBES        DB "Hello granny!",HERO				endif		if RUS        DB "Как тебя зовут, красавица?",SOBES        DB "Я Фёкла Девурдалак, борюсь с",CR        DB "нечистью. Хобби у меня такое. А",CR        DB "как вас зовут?",HERO		else		DB "What is your name beauty?",SOBES        DB "I am Thecla De Goule, and I'm",CR        DB "figthing with evil spirits.",CR		DB "This is my hobby. And what is",CR        DB "your name?",HERO		endif		if RUS        DB "Меня зовут Вера. И хобби у меня",CR        DB "примерно того же толка.",DIALOG,5		else		DB "My name is Vera and I have near",CR        DB "the same hobby.",DIALOG,5		endif		if RUSFK2     DB "Фёкла, ты не поможешь разобраться",CR        DB "с летучими тварями на кладбище?",SOBES        DB "Летучие? Это, наверное, вампиры.",CR        DB "Они не из наших краев. Мало кто",CR        DB "про них знает... Разве что"        DB NEXT        DB "заморские мудрецы про них что-то",CR        DB "могут сказать. Вот только нету их",CR        DB "тут ни одного...",HERO		elseFK2     DB "Thecla, can you help me with the",CR        DB "flying beasts on the cemetery?",SOBES        DB "Flying? This must be a vampires.",CR        DB "They came outside. No one knows",CR        DB "about them... Probably, the"        DB NEXT        DB "foreign wiseacres can tell you",CR        DB "something, but I never saw them",CR        DB "here...",HERO		endif		if RUS        DB "Ха! Чтобы чужими знаниями",CR        DB "пользоваться, мудрецы не нужны.",CR        DB "Знания-то по-разному передаются!",SCRPT,37		else		DB "Ha! You don't need any wiseacres",CR        DB "to use the knowledge.",CR        DB "There are many ways to get the",CR		DB "knowledge!",SCRPT,37		endif		if RUSFK3     DB "Держи, вот книга... Только больно",CR        DB "мудрёная. Я думала проще будет...",SOBES        DB "Сейчас почитаем... Наверное здесь",CR        DB "какой-то шифр: ",34,"Тефебефе",CR        DB "пофомофожефет чефеснофок",34,"..."        DB NEXT        DB "Гммм ",34,"Чефеснофок",34,"... Наречие явно",CR        DB "древнеатлантское.",HERO        DB "И что это значит?",SOBES        DB "Это значит - ",34,"чеснок",34,". Не знаю,",CR        DB "причем он здесь? Ну да ладно,",CR        DB "возьми, авось чего придумаешь...",SCRPT,40		elseFK3     DB "Take this book... It very complex",CR        DB "for me...",SOBES        DB "Let's look... Seem to be, that it",CR        DB "encrypted: ",34,"The garthlic",CR        DB "withll helthp youth",34,"..."        DB NEXT        DB "Hmmm ",34,"Garthlic",34,"... Sounds like",CR        DB "ancient Atlantis.",HERO        DB "And what does it mean?",SOBES        DB "This means - ",34,"garlic",34,". I don't know.",CR        DB "For what? Well fine,",CR        DB "take it, can be useful...",SCRPT,40				endif		if RUSFK4     DB "Охохох... Что же делать...",SOBES        DB "Ой, у меня после той мудрёной",CR        DB "загадки голова болит...",DIALOG,5		elseFK4     DB "Oh... What should I do...",SOBES        DB "Ouch, I got a headache",CR        DB "after this puzzle...",DIALOG,5				endif		if RUSFK5     DB "Как твои дела?",SOBES        DB "Нормально.",END		elseFK5     DB "How are you?",SOBES        DB "I am fine.",END			endif		if RUSFK6     DB "Ты не знаешь, что такого сделать,",CR        DB "чтобы чары Зловета на меня не",CR        DB "действовали?",SOBES        DB 34,"Глаз не видит, сердце не болит,",CR        DB "рука не тянется",34," - Николай",CR        DB "Степанович Ванхельсинг."        DB NEXT        DB "Был, помнится, большим любителем",CR        DB "волчьих ягод и сушеных тараканов.",CR        DB "Что он с ними делал, не знаю, но"        DB NEXT        DB "за девками был охоч подглядывать.",SCRPT,47		elseFK6     DB "Do you know, what should I do to,",CR        DB "neutralize the Zlovet's magic?",SOBES        DB 34,"Eye can't see, heart can't beat,",CR        DB "hand can't take",34," - Arthur",CR        DB "Ignatius Conan Van Helsing."        DB NEXT        DB "He was a big fan of wolfberries",CR        DB "and dried cockroach. I have no idea",CR        DB "what he did with it, but he liked"        DB NEXT        DB "to spy on girls.",SCRPT,47				endif		if RUSFK7     DB "Фёкла, почему со мной никто не",CR        DB "разговаривает?",SOBES        DB "Ванхельсинг? Ты опять за мной",CR        DB "подглядываешь?! А ну пошел прочь!",END		elseFK7     DB "Thecla, why no one talks to me?",SOBES        DB "Van Helsing? Are you spying on",CR        DB "me again?! Go away!",END				endif;           123456789-123456789-123456789-123		if RUSFK8     DB "Тебе это нужно?",SOBES        DB "Спасибо! Давно хочу себе",CR        DB "накладные ногти справить! Возьми",CR        DB "эти зубы и отдай Хевору, а то ему"        DB NEXT        DB "жевать нечем.",SCRPT,63		elseFK8     DB "Do you need this?",SOBES        DB "Thanks! I was dreaming about",CR        DB "false nails! Take these teeth",CR        DB "and bring them to Hevor."        DB NEXT        DB "He cannot chew.",SCRPT,63				endif		if RUSFK9     DB "Фёкла, забери у меня всё, только",CR        DB "помоги мне!",SOBES        DB "Степаныч, поди прочь!",END		elseFK9     DB "Thecla, take all what I have!",CR        DB "Just help me!",SOBES        DB "Ignatius, go away!",END				endifFEND